const AMOUNT_PATTERN = /^(?:0|[1-9]\d{0,9})(?:\.\d{1,2})?$/

/**
 * 计算器键盘表达式求值：把「5+1+3-2」这类加减表达式实时算成整数分。
 * 规则（与自定义数字键盘的输入约束配套）：
 *   - 按 + / - 分段，每段形如 "5" / "5.5"（段内最多两位小数）
 *   - 末段未输完（如 "5+"）该段按 0 计，结果 = 已输完部分
 *   - 开头是运算符（如 "+5"）视为 "0+5"
 *   - 空串 / 无法解析返回 null（调用方据此显示 0.00 或报错）
 * 结果可能为 0 或负数（如 "5-5"），保存前的「必须大于 0」校验由调用方把关。
 */
export function evaluateAmountExpression(expression: string): number | null {
  const text = expression.trim()
  if (!text) return null
  // 段落数字：与 AMOUNT_PATTERN 同规则但允许空前导段（"+5"）与空尾段（"5+"）
  const segmentPattern = /^(?:0|[1-9]\d{0,9})(?:\.\d{1,2})?$/
  const tokens = text.split(/([+-])/).filter((token) => token !== '')
  let totalCents = 0
  let sign = 1
  let sawNumber = false
  for (const token of tokens) {
    if (token === '+' || token === '-') {
      sign = token === '+' ? 1 : -1
      continue
    }
    if (!segmentPattern.test(token)) return null
    const [yuan, fraction = ''] = token.split('.')
    const cents = Number(yuan) * 100 + Number(fraction.padEnd(2, '0').slice(0, 2))
    totalCents += sign * cents
    sawNumber = true
  }
  if (!sawNumber) return null
  if (!Number.isSafeInteger(totalCents)) return null
  return totalCents
}

export function parseAmountToCents(input: string): number {
  const normalized = input.trim().replace(/,/g, '')
  if (!AMOUNT_PATTERN.test(normalized)) {
    throw new Error('请输入最多两位小数的有效金额')
  }
  const [yuan, fraction = ''] = normalized.split('.')
  const cents = Number(yuan) * 100 + Number(fraction.padEnd(2, '0'))
  if (!Number.isSafeInteger(cents) || cents <= 0) {
    throw new Error('金额必须大于 0')
  }
  return cents
}

export function formatCents(cents: number, showSymbol = true): string {
  if (!Number.isSafeInteger(cents)) throw new Error('金额必须是整数分')
  const sign = cents < 0 ? '-' : ''
  const absolute = Math.abs(cents)
  const formatted = `${Math.floor(absolute / 100).toLocaleString('zh-CN')}.${String(absolute % 100).padStart(2, '0')}`
  return `${sign}${showSymbol ? '¥' : ''}${formatted}`
}

export function sumCents(values: readonly number[]): number {
  return values.reduce((sum, value) => {
    if (!Number.isSafeInteger(value)) throw new Error('金额必须是整数分')
    const next = sum + value
    if (!Number.isSafeInteger(next)) throw new Error('金额合计超出安全范围')
    return next
  }, 0)
}
